cityNum, livingCity = map(int, input().split())
criminals = list(map(int, input().split()))

maxDist = max(cityNum - livingCity, livingCity - 1)
checkedDist = 0

sure = 0

while checkedDist <= maxDist:
    leftCity = livingCity - checkedDist
    rightCity = livingCity + checkedDist

    lackNumber = 0
    if leftCity <= 0:
        lackNumber += 1
    if rightCity > cityNum:
        lackNumber += 1

    if leftCity == rightCity:
        if criminals[livingCity - 1] > 0:
            sure += 1
    else:
        if lackNumber == 0:
            if criminals[leftCity - 1] > 0 and criminals[rightCity - 1] > 0:
                sure += 2
        elif lackNumber == 1:
            if (leftCity > 0 and criminals[leftCity - 1] > 0) or (rightCity <= cityNum and criminals[rightCity - 1] > 0):
                sure += 1

    checkedDist += 1

print(sure)

